from ctypes import CDLL, POINTER, c_double, c_int, c_char_p

gsl = CDLL(find_library("gsl"))
gsl.cblas = CDLL(find_library("cblas"), mode=ctypes.RTLD_GLOBAL)

class GSLFunction(ctypes.CDLL):
    _libraries = {'gsl': gsl}

    def __init__(self, func):
        self.func = ctypes.CFUNCTYPE(None, c_double)(func)
        self._as_parameter_ = ctypes.c_void_p(0)

    def __del__(self):
        try:
            self._as_parameter_.value = None
        except AttributeError:
            pass

class CQuadWorkspace(ctypes.Structure):
    _fields_ = [('size', c_int), ('workspace', POINTER(c_double))]

def my_func(x):
    return x**2 + 1.0

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    func_ptr = GSLFunction(func)
    result = ctypes.c_double()
    error = ctypes.c_double()
    neval = ctypes.c_int()

    cquad_ptr = CQuadWorkspace(0, None)
    cquad_ptr.size = workspace_size
    cquad_ptr.workspace = (ctypes.POINTER(c_double)*workspace_size)()

    status = gsl.cquad(gsl.gsl_cquad_my_func, func_ptr._as_parameter_, a, b, epsabs, epsrel, ctypes.byref(cquad_ptr), ctypes.byref(result), ctypes.byref(error), ctypes.byref(neval))

    if status != 0:
        raise Exception('Error in integration: %s' % status)

    return {'integral': result.value, 'error': error.value, 'neval': neval.value}

result = integrate_function(my_func, -1.0, 1.0, 1e-6, 1e-6, 10000)
