class GSLVector(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_double)), ('size', ctypes.c_size_t)]
    def __init__(self, data=None, size=0):
        if data is None:
            self.data = ctypes.POINTER(ctypes.c_double)(ctypes.c_double * size)
            self.size = size
        else:
            self.data = ctypes.cast(data, ctypes.POINTER(ctypes.c_double))
            self.size = len(data)
    def __del__(self):
        if self.data is not None and self.data.contents:
            ctypes.free(self.data)

    @classmethod
    def from_list(cls, list_):
        return cls(np.array(list_, dtype='d').ctypes.data, len(list_))

    @classmethod
    def to_list(cls, vector):
        return [vector.data[i] for i in range(vector.size)]

    def __add__(self, other):
        if not isinstance(other, GSLVector):
            raise TypeError('Can only add a GSLVector')
        new_vector = cls([0.0]*max(self.size, other.size))
        for i in range(min(self.size, other.size)):
            new_vector.data[i] = self.data[i] + other.data[i]
        return new_vector

    def __sub__(self, other):
        if not isinstance(other, GSLVector):
            raise TypeError('Can only subtract a GSLVector')
        new_vector = cls([0.0]*max(self.size, other.size))
        for i in range(min(self.size, other.size)):
            new_vector.data[i] = self.data[i] - other.data[i]
        return new_vector

    def copy(self):
        return GSLVector(self.data, self.size)

