class GSLHistogram(ctypes.Structure):
    _fields_ = [('size', ctypes.c_int),
               ('bin_size', ctypes.c_double),
               ('max_bin_index', ctypes.c_int)]

def analyze_histogram(bin_counts):
    histogram = GSLHistogram()
    histogram.size = len(bin_counts)
    if histogram.size > 0:
        histogram.bin_size = (max(bin_counts) - min(bin_counts)) / (histogram.size - 1)
    else:
        histogram.bin_size = 1.0

    max_bin_index = 0
    min_bin_val = max(bin_counts)
    max_bin_val = min(bin_counts)

    for i in range(histogram.size):
        if bin_counts[i] > 0:
            if bin_counts[i] > max_bin_val:
                max_bin_val = bin_counts[i]
                max_bin_index = i
            elif bin_counts[i] < min_bin_val:
                min_bin_val = bin_counts[i]

    gsl_histogram = ctypes.c_void_p()
    gsl.histogram_init(ctypes.byref(gsl_histogram), histogram.size, histogram.bin_size)

