class PascalDistribution:
    def __init__(self, k, p):
        self.k = k
        self.p = p

    def compute_cdf(self, n):
        cdf = 0.0
        for i in range(n+1):
            cdf += (math.comb(k, i) * (p**i) * ((1-p)**(k-i)))/math.factorial(k)
        return cdf

    def compute_ccdf(self, n):
        ccdf = 0.0
        for i in range(n+1):
            ccdf += (math.comb(k, i) * (p**i) * ((1-p)**(k-i)))/math.factorial(k)
