    # Test cases
    try:
        assert multiset_operation(1) == 0, "Test case 1 failed"
        assert multiset_operation(2) == 0, "Test case 2 failed"
        assert multiset_operation(3) == 0, "Test case 3 failed"
    except ValueError as e:
        assert False, f"Unexpected ValueError: {e}"

    # Error handling test
    try:
        multiset_operation(-1)
    except ValueError:
        pass
    else:
        assert False, "Error handling test failed"
